#include <Wire.h>
#include <MPU6050.h>
MPU6050 mpu;
float last_mag = 0;
void loop() {
    int16_t ax, ay, az;
    mpu.getAcceleration(&ax, &ay, &az);
    float mag = sqrt((float)ax*ax + (float)ay*ay + (float)az*az) / 16384.0f;
    float delta = fabs(mag - last_mag);
    if (delta > {{threshold_g}}) Serial.println("TAP");
    last_mag = mag;
    delay(10);
}
